// src/components/ui/ClientDetail.js
import React, { useState, useEffect } from 'react';
import { clientsAPI } from '../../services/api';
import { X, Phone, MapPin, Mail, CreditCard } from 'lucide-react';

const fmtMoney = (n) => new Intl.NumberFormat('fr-FR').format(n || 0) + ' FCFA';
const fmtDate = (d) => d ? new Date(d).toLocaleDateString('fr-FR') : '—';
const statusBadge = (s) => {
  const map = { ACTIVE: ['badge-info', 'Actif'], COMPLETED: ['badge-success', 'Soldé'], OVERDUE: ['badge-danger', 'En retard'] };
  const [cls, label] = map[s] || ['badge-gray', s];
  return <span className={`badge ${cls}`}>{label}</span>;
};

export default function ClientDetail({ clientId, onClose }) {
  const [client, setClient] = useState(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    clientsAPI.getById(clientId).then(r => {
      setClient(r.data.data);
      setLoading(false);
    }).catch(() => setLoading(false));
  }, [clientId]);

  return (
    <div className="modal-backdrop" onClick={(e) => e.target === e.currentTarget && onClose()}>
      <div className="modal fade-in" style={{ maxWidth: 560 }}>
        <div className="modal-header">
          <h3>Détails du client</h3>
          <button onClick={onClose} className="btn btn-icon btn-outline"><X size={15} /></button>
        </div>
        <div className="modal-body">
          {loading ? <div className="page-loader"><div className="spinner" /></div> : client ? (
            <>
              {/* Client info */}
              <div style={{ display: 'flex', alignItems: 'center', gap: 14, marginBottom: 20, padding: 16, background: 'var(--gray-50)', borderRadius: 10 }}>
                <div style={{
                  width: 48, height: 48, borderRadius: '50%',
                  background: 'var(--primary-subtle)', color: 'var(--primary-light)',
                  display: 'flex', alignItems: 'center', justifyContent: 'center',
                  fontSize: 16, fontWeight: 700,
                }}>{client.name?.slice(0, 2).toUpperCase()}</div>
                <div>
                  <div style={{ fontWeight: 600, fontSize: 16 }}>{client.name}</div>
                  <div style={{ fontSize: 12, color: 'var(--gray-500)' }}>Inscrit le {fmtDate(client.registeredAt)}</div>
                </div>
              </div>
              <div style={{ display: 'flex', flexDirection: 'column', gap: 10, marginBottom: 24 }}>
                {[
                  { icon: Phone, label: client.phone },
                  { icon: MapPin, label: client.address },
                  ...(client.email ? [{ icon: Mail, label: client.email }] : []),
                ].map(({ icon: Icon, label }) => (
                  <div key={label} style={{ display: 'flex', alignItems: 'center', gap: 10, fontSize: 13 }}>
                    <Icon size={14} color="var(--gray-400)" />
                    <span>{label}</span>
                  </div>
                ))}
              </div>

              {/* Loans */}
              <div>
                <div style={{ display: 'flex', alignItems: 'center', gap: 8, marginBottom: 12 }}>
                  <CreditCard size={14} color="var(--primary)" />
                  <h4 style={{ fontSize: 13, fontWeight: 600 }}>Prêts ({client.loans?.length || 0})</h4>
                </div>
                {!client.loans?.length ? (
                  <p style={{ color: 'var(--gray-400)', fontSize: 13 }}>Aucun prêt enregistré</p>
                ) : (
                  <div style={{ display: 'flex', flexDirection: 'column', gap: 10 }}>
                    {client.loans.map((loan) => (
                      <div key={loan._id} style={{ padding: 14, border: '1px solid var(--gray-200)', borderRadius: 10 }}>
                        <div style={{ display: 'flex', justifyContent: 'space-between', marginBottom: 8 }}>
                          <span style={{ fontWeight: 600, fontSize: 15 }}>{fmtMoney(loan.amount)}</span>
                          {statusBadge(loan.status)}
                        </div>
                        <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 6, fontSize: 12, color: 'var(--gray-500)' }}>
                          <span>Taux : {loan.interestRate}%</span>
                          <span>Durée : {loan.duration} mois</span>
                          <span>Intérêt : {fmtMoney(loan.interest)}</span>
                          <span>Total : {fmtMoney(loan.totalRepayable)}</span>
                        </div>
                      </div>
                    ))}
                  </div>
                )}
              </div>
            </>
          ) : <p>Client introuvable</p>}
        </div>
      </div>
    </div>
  );
}
